{
    if (!HasPrintSubjectMark())
        return "";

    StringBuilder sb = new StringBuilder();
    int intSubjectCount = dtbSubjectList.Rows.Count;
    double dblSubjectWidth = 40.0 / intSubjectCount;
    if (dblSubjectWidth > 8)
        dblSubjectWidth = 8;
    if (dblSubjectWidth < 3)
        dblSubjectWidth = 3;

    for (int i = 0; i < intSubjectCount; i++)
        sb.Append(String.Format("<col style=\"width:{0:0.#}%\" />", dblSubjectWidth));

    return sb.ToString();
}

