        string strName = drwSubject["SubjectName"].ToString();
        if (strName == "")
            strName = drwSubject["SubjectShortName"].ToString();

        sb.Append("<th class=\"subject-col\">");
        sb.Append(strName != "" ? strName : "&nbsp;");
        sb.Append("</th>");
    }
    return sb.ToString();
}

private string BuildPrintSubjectMarkCellsHTML(DataRow drw)
{
    if (!HasPrintSubjectMark())
        return "";

    StringBuilder sb = new StringBuilder();
    foreach (DataRow drwSubject in dtbSubjectList.Rows)
