private string NormalizePrintLevel(string strLevel)
{
    if (strLevel == null)
        return "";
    return strLevel.Trim();
}

private string CalcLearningLevelFromTBC(double dblTBC)
{
    if (dblTBC < 4)
        return "Kém";
    if (dblTBC < 5)
        return "Yếu";
    if (dblTBC < 6)
        return "Trung bình";
    if (dblTBC < 7.0)
        return "TB khá";
    if (dblTBC < 8)
        return "Khá";
    if (dblTBC < 9)
        return "Giỏi";
    return "Xuất sắc";
}

private string GetPrintLevelForSummary(DataRow drw)
{
    if (IsEligibleForPrint(drw) && HasTBC(drw))
        return CalcLearningLevelFromTBC(Convert.ToDouble(drw["LearningSummary"]));

    string strLevel = NormalizePrintLevel(GetPrintLevel(drw));
    if (strLevel != "" && strLevel != "Không đạt")
        return strLevel;

    if (HasTBC(drw))
        return CalcLearningLevelFromTBC(Convert.ToDouble(drw["LearningSummary"]));

    return "";
}

