}

private bool HasZeroSubjectMark(DataRow drw)
{
    if (drw == null || drw.Table == null)
        return false;

    if (dtbSubjectList != null && dtbSubjectList.Rows.Count > 0)
    {
        foreach (DataRow drwSubject in dtbSubjectList.Rows)
        {
            string strIndex = drwSubject["SubjectIndex"].ToString();
            if (strIndex == "")
                continue;

            string strFieldName = "FinalSummary_" + strIndex;
            if (!drw.Table.Columns.Contains(strFieldName))
                continue;

            if (drw[strFieldName] == null || drw[strFieldName] == DBNull.Value)
                continue;

            double dblMark;
            if (double.TryParse(drw[strFieldName].ToString(), out dblMark) && dblMark == 0)
                return true;
        }
        return false;
    }

    foreach (DataColumn col in drw.Table.Columns)
    {
        if (!col.ColumnName.StartsWith("FinalSummary_"))
            continue;

        if (drw[col] == null || drw[col] == DBNull.Value)
            continue;

        double dblMark;
        if (double.TryParse(drw[col].ToString(), out dblMark) && dblMark == 0)
            return true;
    }
    return false;
}

private bool IsTBC_Passed(DataRow drw)
{
    if (!HasTBC(drw))
        return false;
    if (Convert.ToDouble(drw["LearningSummary"]) <= 5)
        return false;
    if (HasZeroSubjectMark(drw))
        return false;
    return true;
}

